#include <iostream>
#include <sstream>
#include <string>

std::string componer_resumen(int validos, int rechazados) {
    std::ostringstream texto;
    texto << "Valides=" << validos << ";Rejetés=" << rechazados;
    return texto.str();
}

int main() {
    std::string primero = componer_resumen(2, 1);
    std::string segundo = componer_resumen(0, 0);
    std::cout << primero << "\n" << segundo;
    return 0;
}

#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::ostringstream texto;
    texto << "Valides=" << 2 << ";Rejetés=" << 1;
    std::string mensaje = texto.str();
    std::ofstream salida{"resumen_lgp.txt"};
    if (!salida) {
        std::cout << "Erreur d'ouverture";
        return 1;
    }
    salida << mensaje;
    salida.close();
    if (!salida) {
        std::cout << "Erreur d'écriture";
        return 1;
    }
    std::cout << "Enregistré";
    return 0;
}
